/**
 * Webhook endpoints and their delivery history (`client.webhooks`), mirroring
 * `sandfort_sdk.webhooks`. Every route needs the `webhooks:write` scope. The signing secret is
 * generated by the server and comes back on the answer of `create` only.
 */

import { ValidationError } from "./errors.js";
import { paginate, type Cursor } from "./pagination.js";
import {
  asArray,
  asRecord,
  pageFromPayload,
  requiredString,
  stringOrNull,
  timestampOrNull,
  type Page,
} from "./models.js";
import { callArgs, type CallOptions } from "./resilience.js";
import { withHiddenSecret } from "./secret.js";
import type { Transport } from "./transport.js";
import {
  requireListLimit,
  requireNonBlank,
  requireOptionalNonBlank,
  requireStringList,
} from "./validation.js";

export const WEBHOOKS_PATH = "/v1/webhooks";
export const DELIVERY_STATES = ["pending", "delivered", "failed", "disabled"] as const;
export type DeliveryState = (typeof DELIVERY_STATES)[number];

export interface WebhookEndpoint {
  id: string;
  url: string;
  enabled: boolean;
  /** Event type filters such as `sandbox.started`, `sandbox.*` or `*`. */
  eventTypes: readonly string[];
  failureCount: number;
  createdAt: Date | null;
  /**
   * The signing secret: present on the answer of `create` only. It is not enumerable, so it
   * stays out of `JSON.stringify`, `Object.keys` and `console.log`.
   */
  readonly secret?: string;
}

/** One entry of a delivery's history: an attempt, or a `redelivered` marker. */
export interface DeliveryAttempt {
  kind: string;
  attemptedAt: Date | null;
  /** HTTP status the endpoint answered; `null` when none came back. */
  status: number | null;
  error: string | null;
  durationMs: number | null;
  /** The API key that requeued the delivery (markers only). */
  actorId: string | null;
}

export interface WebhookDelivery {
  id: string;
  endpointId: string;
  eventId: string;
  /** `pending`, `delivered`, `failed` or `disabled`. */
  state: string;
  attempts: number;
  eventType: string | null;
  nextAttemptAt: Date | null;
  lastStatus: number | null;
  lastError: string | null;
  /** Hex sha256 of the signed body; the body itself is not stored. */
  payloadSha256: string | null;
  /** Oldest first. */
  attemptHistory: readonly DeliveryAttempt[];
  createdAt: Date | null;
  updatedAt: Date | null;
}

export interface CreateWebhookOptions extends CallOptions {
  /** Left out of the request unless given (the server default is enabled). */
  enabled?: boolean;
}

export interface UpdateWebhookOptions extends CallOptions {
  url?: string;
  events?: readonly string[];
  enabled?: boolean;
}

export interface ListDeliveriesOptions extends CallOptions {
  eventType?: string;
  state?: DeliveryState;
  /** A page's `nextCursor`, passed back as is; bound to the endpoint and to the filters. */
  cursor?: Cursor;
  /** 1 to 100 (server default 50). */
  limit?: number;
}

/** Filters for `deliveriesAll`: the same on every page, so no cursor. */
export type ListDeliveriesFilters = Omit<ListDeliveriesOptions, "cursor">;

function numberOrNull(value: unknown): number | null {
  return typeof value === "number" ? value : null;
}

function attemptFromPayload(data: unknown): DeliveryAttempt {
  const raw = asRecord(data, "delivery attempt");
  const kind = stringOrNull(raw["kind"]);
  return {
    kind: kind === null || kind === "" ? "attempt" : kind,
    attemptedAt: timestampOrNull(raw["attempted_at"], "delivery attempt"),
    status: numberOrNull(raw["status"]),
    error: stringOrNull(raw["error"]),
    durationMs: numberOrNull(raw["duration_ms"]),
    actorId: stringOrNull(raw["actor_id"]),
  };
}

export function endpointFromPayload(data: unknown): WebhookEndpoint {
  const what = "webhook endpoint";
  const raw = asRecord(data, what);
  const types = raw["event_types"];
  const failures = raw["failure_count"];
  const endpoint: WebhookEndpoint = {
    id: requiredString(raw, "id", what),
    url: requiredString(raw, "url", what),
    enabled: typeof raw["enabled"] === "boolean" ? raw["enabled"] : true,
    eventTypes: Array.isArray(types) ? types.map(String) : [],
    failureCount: typeof failures === "number" ? failures : 0,
    createdAt: timestampOrNull(raw["created_at"], what),
  };
  return withHiddenSecret(endpoint, "secret", stringOrNull(raw["secret"]) ?? undefined);
}

export function deliveryFromPayload(data: unknown): WebhookDelivery {
  const what = "webhook delivery";
  const raw = asRecord(data, what);
  const history = raw["attempt_history"];
  return {
    id: requiredString(raw, "id", what),
    endpointId: requiredString(raw, "endpoint_id", what),
    eventId: requiredString(raw, "event_id", what),
    state: requiredString(raw, "state", what),
    attempts: typeof raw["attempts"] === "number" ? raw["attempts"] : 0,
    eventType: stringOrNull(raw["event_type"]),
    nextAttemptAt: timestampOrNull(raw["next_attempt_at"], what),
    lastStatus: numberOrNull(raw["last_status"]),
    lastError: stringOrNull(raw["last_error"]),
    payloadSha256: stringOrNull(raw["payload_sha256"]),
    attemptHistory:
      history === undefined || history === null
        ? []
        : asArray(history, "delivery attempt history").map(attemptFromPayload),
    createdAt: timestampOrNull(raw["created_at"], what),
    updatedAt: timestampOrNull(raw["updated_at"], what),
  };
}

function endpointPath(endpointId: string): string {
  requireNonBlank(endpointId, "endpointId");
  return `${WEBHOOKS_PATH}/${encodeURIComponent(endpointId)}`;
}

function deliveriesPath(endpointId: string): string {
  return `${endpointPath(endpointId)}/deliveries`;
}

function deliveryPath(endpointId: string, deliveryId: string): string {
  requireNonBlank(deliveryId, "deliveryId");
  return `${deliveriesPath(endpointId)}/${encodeURIComponent(deliveryId)}`;
}

/** Wire body for `POST /v1/webhooks`. */
export function webhookCreateBody(
  url: string,
  events: readonly string[],
  enabled: boolean | undefined,
): Record<string, unknown> {
  requireNonBlank(url, "url");
  requireStringList(events, "events");
  return { url, event_types: [...events], ...(enabled === undefined ? {} : { enabled }) };
}

/** Wire body for `PATCH /v1/webhooks/{id}`: only the given fields. */
export function webhookUpdateBody(options: UpdateWebhookOptions): Record<string, unknown> {
  const body: Record<string, unknown> = {};
  if (options.url !== undefined) {
    requireNonBlank(options.url, "url");
    body["url"] = options.url;
  }
  if (options.events !== undefined) {
    requireStringList(options.events, "events");
    body["event_types"] = [...options.events];
  }
  if (options.enabled !== undefined) body["enabled"] = options.enabled;
  if (Object.keys(body).length === 0) {
    throw new ValidationError("nothing to update: pass url, events or enabled");
  }
  return body;
}

function deliveriesQuery(
  options: ListDeliveriesOptions,
): Record<string, string | number | undefined> {
  requireOptionalNonBlank(options.eventType, "eventType");
  requireListLimit(options.limit);
  const { state } = options;
  if (state !== undefined && !DELIVERY_STATES.includes(state)) {
    throw new ValidationError(
      `state must be one of ${DELIVERY_STATES.join(", ")}; got ${JSON.stringify(state)}`,
    );
  }
  const cursor = options.cursor ?? undefined;
  requireOptionalNonBlank(cursor, "cursor");
  return { event_type: options.eventType, state, cursor, limit: options.limit };
}

export class Webhooks {
  readonly #transport: Transport;

  constructor(transport: Transport) {
    this.#transport = transport;
  }

  /**
   * Register an endpoint; the answer carries the signing `secret`, shown once. `events` are
   * event type filters (`"sandbox.started"`, `"sandbox.*"`, `"*"`); an empty list is sent as
   * is and the server decides what that selects. A create is never resent after a failure.
   */
  async create(
    url: string,
    events: readonly string[],
    options: CreateWebhookOptions = {},
  ): Promise<WebhookEndpoint> {
    const reply = await this.#transport.request("POST", WEBHOOKS_PATH, {
      json: webhookCreateBody(url, events, options.enabled),
      ...callArgs(options),
    });
    return endpointFromPayload(reply);
  }

  async list(call: CallOptions = {}): Promise<readonly WebhookEndpoint[]> {
    const reply = await this.#transport.request("GET", WEBHOOKS_PATH, { ...callArgs(call) });
    return asArray(reply, "webhook endpoints").map(endpointFromPayload);
  }

  async get(endpointId: string, call: CallOptions = {}): Promise<WebhookEndpoint> {
    const reply = await this.#transport.request("GET", endpointPath(endpointId), {
      ...callArgs(call),
    });
    return endpointFromPayload(reply);
  }

  /** Change the given fields only; re-enabling an endpoint resets its failure count. */
  async update(
    endpointId: string,
    options: UpdateWebhookOptions,
  ): Promise<WebhookEndpoint> {
    const path = endpointPath(endpointId);
    const reply = await this.#transport.request("PATCH", path, {
      json: webhookUpdateBody(options),
      ...callArgs(options),
    });
    return endpointFromPayload(reply);
  }

  /** Delete an endpoint; the answer is the endpoint as it was. */
  async delete(endpointId: string, call: CallOptions = {}): Promise<WebhookEndpoint> {
    const reply = await this.#transport.request("DELETE", endpointPath(endpointId), {
      ...callArgs(call),
    });
    return endpointFromPayload(reply);
  }

  /**
   * One page of an endpoint's deliveries in id order. `eventType` and `state` filter on the
   * server and a cursor is bound to them, so page on with the same ones. A filtered page may
   * be short or empty while `nextCursor` is set: keep going until it is `null`.
   */
  async deliveries(
    endpointId: string,
    options: ListDeliveriesOptions = {},
  ): Promise<Page<WebhookDelivery>> {
    const path = deliveriesPath(endpointId);
    const reply = await this.#transport.requestEnvelope("GET", path, {
      query: deliveriesQuery(options),
      ...callArgs(options),
    });
    return pageFromPayload(reply.data, reply.nextCursor, deliveryFromPayload);
  }

  /** Every delivery of `deliveries`, page by page with the same filters, until the last. */
  deliveriesAll(
    endpointId: string,
    filters: ListDeliveriesFilters = {},
  ): AsyncGenerator<WebhookDelivery, void, undefined> {
    return paginate((cursor) => this.deliveries(endpointId, { ...filters, cursor }));
  }

  /** One delivery with its outcome and attempt history. */
  async getDelivery(
    endpointId: string,
    deliveryId: string,
    call: CallOptions = {},
  ): Promise<WebhookDelivery> {
    const reply = await this.#transport.request("GET", deliveryPath(endpointId, deliveryId), {
      ...callArgs(call),
    });
    return deliveryFromPayload(reply);
  }

  /** Requeue a `failed` or `disabled` delivery (any other state answers 409). Never resent. */
  async redeliver(
    endpointId: string,
    deliveryId: string,
    call: CallOptions = {},
  ): Promise<WebhookDelivery> {
    const path = `${deliveryPath(endpointId, deliveryId)}/redeliver`;
    const reply = await this.#transport.request("POST", path, { ...callArgs(call) });
    return deliveryFromPayload(reply);
  }
}
